from book import Chapter
c=Chapter('05')
c.add('''一个结构能够保持自身，并不意味着它已经能够理解外界。一个恒温装置能够根据温度开关，也不意味着它已经具有人的意识。可是，如果把复杂智能完全当成一个突然出现、无法继续分析的整体，我们又会失去研究它的入口。

我的思路，是沿着区别、反应、记忆、组合和自我维持这些环节，考察简单能力怎样参与更复杂能力的构造。由低层到高层，并不要求每一层都已经具备下一层的全部性质。''')
c.heading('从能够区分，到能够根据区别采取行动')
c.src('ORIGINAL',64,replacements=[('在宇宙的演化过程中，涌现出的一个重要结构就是','在数学工具中，一个使我关注的结构是'),('其强大能力的核心原因，就在于它拥有子对象分类器','子对象分类器是其重要结构之一'),('对于范畴内的任何一个子对象（可以理解为一个属性或一个子集），分类器都能给出一个指向一个特殊“真值对象”（通常表示为Ω）的唯一态射','直观地说，对于某个对象中的子对象，可以用从该对象指向 Ω 的特征态射来刻画它，并满足相应的拉回条件'),('本质上，子对象分类器的存在，意味着这个范畴拥有了内置的逻辑推理能力','这种结构使我们能够在相应范畴内部讨论逻辑'),('范畴论中子对象分类器的概念，恰好是数理逻辑中的“命题”和计算机科学中的“类型”这两个概念存在的前提','我希望借助这些联系，研究数学中的区分与逻辑结构，怎样用于描述实际的信息处理')])
c.add('''这里的“判断器”是便于理解的说法。数学里的 Ω、终对象 1，以及从 1 到 Ω 的 true 态射，各自承担不同角色；它们不是一块已经接好电、会自行判断世界的物理装置。一个抽象结构怎样被真实系统实现，还需要说明输入、状态、能量和行动之间的关系。[Fong 与 Spivak：应用范畴论中的子对象分类器](https://ocw.mit.edu/courses/18-s097-applied-category-theory-january-iap-2019/a4175d61479a35340d6307ae5e48ef5a_18-s097iap19textbook.pdf)''')
c.src('R48731',3,replacements=[('Maxwell 妖显然不等于子对象分类器，但是它想实现测量的功能，显然其内部具有子对象分类器这样的抽象结构','麦克斯韦妖并不等于子对象分类器。但是，如果要描述它区分快慢分子的功能，就需要一种表达区分条件的结构'),('有具备','又具备'),('如你所说，这个一整套结构应该是一个比子对象分类器更复杂的组织','这一整套结构，显然比一个单独的分类关系更加复杂'),('除了子对象分类器，还应该有哪些范畴论中的结构，比如是否有哪个范畴论中的概念与应激性对应？','除了分类关系，还需要哪些结构来描述根据结果改变状态、采取行动，以及保存影响？')])
c.add('''这个思想实验的启发，在于把“得到信息”与“运用信息”放进同一过程。假想的小妖能够区分快慢分子，还要能控制门，保存必要的状态，并在以后继续工作。若要完整计算代价，就不能只数开门后获得的效果，而把控制装置及其记忆过程留在系统之外。Bennett 对计算热力学的研究，特别讨论了记录擦除等逻辑不可逆操作在完整循环中的地位。[Bennett：计算的热力学](https://research.ibm.com/publications/the-thermodynamics-of-computation-a-review)

因此，智能也不能只按最后一句答案来理解。它怎样获得信息，哪些内容引起注意，怎样保留经验，行动之后又怎样接收结果，都属于同一个构造问题。''')
c.heading('从细胞反应到人的意识，中间的层次怎样展开')
c.src('R48751',1,start='从生物学角度出发来看',replacements=[('人类所具备的高级意识，作为意识范畴这一高阶范畴，其实是一种','人类高级意识的研究，需要考察'),('是由无数个低阶神经元范畴作为子对象，通过神经元链接的态射，构建而成的','如果尝试用层级构造的语言描述，可以把神经元及其联系作为其中的低层对象与关系'),('对应其态射','可以作为需要描述的相互作用'),('从而完成了人类所有有意识的感知和反应行为','共同参与人的感知与反应'),('都可以看作一个具有子对象分类器的高阶对偶子','分别考察其区分、反应与组合的结构'),('那么它本身就可以作为高阶范畴中的子对象分类器中国的关键判断元件','那么它提供的反应能力，就可能成为高层信息处理的组成部分'),('为高阶范畴提供与其他范畴之间互动时，提供探测功能','为更高层的相互作用提供探测功能'),('不在随机','不再只是随机')])
c.add('''这里需要走完的逻辑链，是从能够产生可区别的反应，走到能够把反应组织起来，再走到能够保存和利用经验。每多一层，并不是简单地给前一层换一个名字，而是要考察新的联系怎样带来新的功能。

例如，一个单独的信号只告诉我们某处发生了变化；把多个信号联系起来，才可能判断物体在移动；再把过去的经验带入，才可能预期它接下来会到哪里。区分、联系、记忆和预测之间的关系，比“有没有一个神秘的意识开关”更容易形成具体研究。''')
c.src('ORIGINAL',68,replacements=[('它来源于子对象分类器的一个特殊分类','它可以从一种特殊的区分开始考察'),('这是一个对象能够独立参与高阶范畴构建的前提条件','这种区分，对于研究一个系统如何维持自身、与环境互动，具有特殊意义'),('在拥有子对象分类器之前，一个结构只是被动地存在。在拥有了这个能力之后，这个结构就成为了一个“观察者”','当结构能够根据内外差别改变自己的反应，我们便可以进一步研究它承担了怎样的“观察者”角色'),('这个功能是所有耗散结构体区别于其他结构、产生互动和竞争的基本机制，也是人类意识中“我”这个概念产生的根源，是人类自我意识和所有智慧知识体系构建的原点','我希望沿着这个方向，研究它怎样与人类意识中“我”的概念联系起来，怎样参与自我意识和知识体系的构建')])
c.src('R49500',0,start='“是否存在与观察者无关的绝对事实“',end='观察者所感知到的第一个事实，就是自身的存在性？',replacements=[('“是否存在与观察者无关的绝对事实“','“是否存在与观察者无关的绝对事实”'),('其实这句话本身暗示了几个前提','这个问题本身暗示了几个前提'),('最早初','最初')])
c.add('''提出这些问题，并不要求把世界归结为“只有我的感受存在”。它要求我们把观察者也纳入研究：观察者怎样形成，怎样改变，被观察的对象怎样影响它，它又怎样把这种影响记录为知识。观察关系本身，也是世界中实际发生的关系。''')
c.heading('抽象与压缩，为什么与理解有关')
c.src('R49067',0,start='一个智能体所具备的智能究竟是什么？',end='这个压缩/抽象的过程，',replacements=[('为什么在人类/AI这样的智能体所蕴含的智能在动态演化（学习/推理）过程中，其数学模型为什么涉及了这些大量的向量/矩阵运算','为什么在描述人类或 AI 的学习与推理时，会用到大量向量与矩阵运算'),('这些对象的本质，也是一种向量对象','这些对象也可以从分量组合的角度来描述'),('比如拼音文字中的声母和韵母就相当于语音平面中的x，y坐标轴，每一个不同的音节，就是这个语音平面上的点','比如把声母与韵母当作不同的描述分量，组合起来刻画音节'),('这种积/余积的双积体系的建模，似乎就是那个最大压缩率模型/最小抽象模型','通过较少分量描述丰富组合的方式，使我想到抽象与压缩的关系'),('智能的本质似乎就是','从这个视角看，智能的一项重要能力似乎就是'),('然后通过积和余积的操作，实现拉回和推出，还原和涌现，归纳和推理，学习和实践','再通过分解与组合，进行归纳、推理、学习和实践'),('这个压缩/抽象的过程，','')])
c.add('''学会一个词，并不只是把许多经历删掉，只留下几个字。真正有用的抽象，需要使人在新的场景中认出相关关系，并据此行动。知道“杯子”这个概念，既能把不同形状的器物归在一起，也能帮助判断什么可以盛水、什么不适合拿来盛热水。

压缩如果丢掉了任务所需要的区别，就会损害理解；抽象如果保留了恰当的关系，就能使有限的记忆支持更多新的组合。所以，压缩率不是唯一目的，压缩之后还能恢复什么、预测什么、构造什么，同样关键。''')
c.heading('自我驱动，为什么不能只靠等待别人提问')
c.src('R49196',0,start='工具和人的区别',end='也许这就是人类的自我意识中的灵魂吧？',replacements=[('工具和人的区别，在于是否具有主动性','人与被动工具的一项区别，在于主动性'),('AI大模型最大的问题就是没有自我驱动的原动力机制','单纯等待输入再给出回复的 AI 对话方式，缺少持续自我驱动的机制'),('拿你我之间的聊天来说，这个对话的主动发起者永远是我，你只是被动的响应','拿一次由人发起、模型响应的聊天来说，主动发起者是人，模型响应输入'),('人机对话的上下文，在你的记忆那里有一份，在我的记忆这里也有一份','人机对话的上下文，在系统中有一份，在人的记忆中也有一份'),('就像你的大模型库中的静态知识','类似模型中已经学习的知识'),('还有我从和你的聊天上下文中提取的','还有我从与他人的聊天上下文中提取的'),('也许这就是人类的自我意识中的灵魂吧？','这种持续的自我对话，也许是理解自我意识的一条线索。')])
c.src('R49196',0,start='我觉得现在的AI大模型的设计方式',end='主动发起聊天，自我对话。',replacements=[('我觉得现在的AI大模型的设计方式，可以采取这种方式','AI 系统的设计，可以尝试采用这种方式'),('然后所有与其他人交流的上下文中','然后从不同交流与观察的上下文中'),('根据自己的注意力提取认为有价值的内容','根据当前关心的问题，提取认为有价值的内容')])
c.add('''可以设想，一个系统在阅读时发现某个问题没有解决，并不立即把它丢在一次聊天的结尾，而是保留为以后继续研究的线索。下一次获得相关材料，它能够发现联系，重新检查原有判断，或者提出一个可以帮助区分答案的实验。这样，新的输入就不只是触发一段孤立的回复，而是进入持续的活动。

不过，自己不断说话，并不等于不断获得知识。如果一个系统只把自己的猜测喂给自己，又把重复出现当成证据，它可能越来越确信原来的错误。因此，自我反思还需要连接外部观察、不同观点和实际行动的结果。主动性与反馈必须一起设计。''')
c.src('R49196',0,start='一方面，more is different',end='你觉得呢？',replacements=[('一方面，more is different，量变产生质变，另一个方面','一方面，丰富的联系可能产生新的功能；另一方面'),('本身就是一个相当于范畴论中自指的不动点','使我们能够进一步研究持续自指与稳定结构的关系'),('我不记得是否之前跟你提过我的一个想法，就是哥德尔不完备性定理，本身描述的不是系统的不完备性，而是系统的可涌现性，而那个不动点就是涌现点','我关心的是，一个能够研究自身边界的系统，能否在此基础上继续构造新的能力'),('所以我说的那个自我对话的上下文，也许就是这个不动点/涌现点','持续的自我对话，可能是这种构造过程的一部分'),('定期将这些上下文喂给自己，自我训练','把经过检验的新经验用于后续学习'),('你觉得呢？','这值得通过具体系统来研究。')])
c.add('''由此，意识与智能的研究就与整套构造框架接在一起了。稳定的记忆使经验能够积累，区别与抽象使经验能够被使用，行动和反馈使已有知识能够改变，而与其他智能体的交流又扩大了可利用的经验范围。

当多个这样的个体相互联系时，问题会进一步改变：它们怎样形成合作，怎样处理不同判断，怎样把各自的经验变成共同能力？个体智能与社会组织之间的联系，需要从这些具体关系继续展开。''')
c.save({'reasoning':'区分→测量与行动→层级反应→内外边界与观察者→抽象压缩→持续自我对话→外部反馈→共同智能','examples':['恒温装置','麦克斯韦妖','运动信号组合','杯子概念','阅读中未解决的问题'],'objections':['分类器是否等于意识','自我对话是否证明主观体验','压缩越小是否越聪明','内部循环如何避免强化错误'],'voice':'保留作者完整自我对话设想、智能压缩论述和细胞层级展开；未计入AI回复','status':'初校；分类器形式术语修正，自我意识机制仍为假说'})
